```python
"""Módulo de gestión de cola de tareas offline para procesamiento local."""

from dataclasses import dataclass, field
from pathlib import Path
import json
import time
from typing import Optional


@dataclass
class TareaLocal:
    identificador: str
    ruta_archivo: Path
    prioridad: int = 5
    estado: str = "pendiente"
    reintentos: int = 0
    creada_en: float = field(default_factory=time.time)
    error_ultimo: Optional[str] = None

    def marcar_en_curso(self) -> None:
        self.estado = "en_curso"

    def marcar_completada(self) -> None:
        self.estado = "completada"
        self.error_ultimo = None

    def marcar_error(self, mensaje: str) -> None:
        self.reintentos += 1
        self.error_ultimo = mensaje
        self.estado = "fallida" if self.reintentos >= 3 else "pendiente"


class ColaTareasOffline:
    """Cola persistente en JSON para trabajos de indexación y análisis."""

    def __init__(self, ruta_estado: Path, max_reintentos: int = 3) -> None:
        self.ruta_estado = ruta_estado
        self.max_reintentos = max_reintentos
        self._tareas: dict[str, TareaLocal] = {}

    def agregar(self, identificador: str, ruta_archivo: Path, prioridad: int = 5) -> TareaLocal:
        if identificador in self._tareas:
            return self._tareas[identificador]
        tarea = TareaLocal(
            identificador=identificador,
            ruta_archivo=ruta_archivo,
            prioridad=prioridad,
        )
        self._tareas[identificador] = tarea
        return tarea

    def siguiente_pendiente(self) -> Optional[TareaLocal]:
        candidatas = [t for t in self._tareas.values() if t.estado == "pendiente"]
        if not candidatas:
            return None
        candidatas.sort(key=lambda t: (t.prioridad, t.creada_en))
        return candidatas[0]

    def listar_por_estado(self, estado: str) -> list[TareaLocal]:
        return [t for t in self._tareas.values() if t.estado == estado]

    def contar_resumen(self) -> dict[str, int]:
        resumen = {"pendiente": 0, "en_curso": 0, "completada": 0, "fallida": 0}
        for t in self._tareas.values():
            resumen[t.estado] = resumen.get(t.estado, 0) + 1
        return resumen

    def guardar(self) -> None:
        datos = []
        for t in self._tareas.values():
            datos.append({
                "identificador": t.identificador,
                "ruta_archivo": str(t.ruta_archivo),
                "prioridad": t.prioridad,
                "estado": t.estado,
                "reintentos": t.reintentos,
                "creada_en": t.creada_en,
                "error_ultimo": t.error_ultimo,
            })
        self.ruta_estado.parent.mkdir(parents=True, exist_ok=True)
        self.ruta_estado.write_text(json.dumps(datos, ensure_ascii=False, indent=2), encoding="utf-8")

    def cargar(self) -> int:
        if not self.ruta_estado.exists():
            return 0
        bruto = json.loads(self.ruta_estado.read_text(encoding="utf-8"))
        self._tareas.clear()
        for item in bruto:
            t = TareaLocal(
                identificador=item["identificador"],
                ruta_archivo=Path(item["ruta_archivo"]),
                prioridad=int(item.get("prioridad", 5)),
                estado=str(item.get("estado", "pendiente")),
                reintentos=int(item.get("reintentos", 0)),
                creada_en=float(item.get("creada_en", 0.0)),
                error_ultimo=item.get("error_ultimo"),
            )
            self._tareas[t.identificador] = t
        return len(self._tareas)

# --- Módulo auxiliar 01: gestor de caché y validación ---
class GestorSegmento01:
    """Administra bloques de índice 01 con verificación de integridad."""

    def __init__(self, ruta_base: str, limite_mb: int = 144) -> None:
        self.ruta_base = ruta_base
        self.limite_bytes = limite_mb * 1024 * 1024
        self.registros: dict[str, dict[str, int]] = {}

    def registrar_bloque(self, clave: str, tamano: int, version: int = 1) -> bool:
        if tamano <= 0 or tamano > self.limite_bytes:
            return False
        actual = self.registros.get(clave)
        if actual and actual["version"] >= version:
            return False
        self.registros[clave] = {"tamano": tamano, "version": version}
        return True

    def resumen_uso(self) -> tuple[int, int]:
        total = sum(item["tamano"] for item in self.registros.values())
        return len(self.registros), total

